window.RP_SESSION={"id":"S-e74bc28bf432","messages":[{"id":"RP-II-0098250","time":"2026-05-08T00:07:00+09:00","room":"RP II","name":"단델리온","profile":"단델리온","identity":"reviewed","type":"dialogue","body":"쾅—!!\n\n길드 홀의 낡은 문이 거칠게 흔들렸다.\n천장에 매달린 잔 조명이 미세하게 흔들리고, 벽에 기대 세워둔 창 몇 자루가 덜컹거리는 소리를 냈다.\n\n그리고 다시.\n콰앙! 쾅!!","characters":["P-df0906c0708a"]},{"id":"RP-II-0098251","time":"2026-05-08T00:11:00+09:00","room":"RP II","name":"단델리온","profile":"단델리온","identity":"reviewed","type":"dialogue","body":"세 번째 충격 끝에, 결국 길드 홀의 문이 안쪽으로 밀려 열렸다.\n\n문턱 너머에는 거대한 체구의 남자가 서 있었다.\n빗물에 젖은 망토 끝에서 물방울이 천천히 바닥으로 떨어졌다. 어두운 강철빛 갑옷은 희미한 조명 아래에서도 둔탁하게 빛을 삼키고 있었고, 가슴 한가운데 새겨진 작은 민들레 음각만이 가까스로 형태를 드러냈다.","characters":["P-df0906c0708a"]},{"id":"RP-II-0098252","time":"2026-05-08T00:19:00+09:00","room":"RP II","name":"단델리온","profile":"단델리온","identity":"reviewed","type":"dialogue","body":"\"클램시는 아직 살아있는가?\"","characters":["P-df0906c0708a"]},{"id":"RP-II-0098253","time":"2026-05-08T00:19:00+09:00","room":"RP II","name":"단델리온","profile":"단델리온","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-df0906c0708a"]},{"id":"RP-II-0098254","time":"2026-05-08T00:19:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
